window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-23080b25cdd4f298"]={"versions": [{"id": "FIG-23080b25cdd4f298", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm) mit Referenzierungsfragment (<code>ref</code>) und kombiniertem Fragment (<code>alt</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses zur Beantwortung einer zuvor empfangenen J1939-Anfrage (PGN 59904 / <code>Request PDU</code>) für eine Diagnose-PDU (z. B. DM-Nachrichten wie DM1–DM5) innerhalb des AUTOSAR Classic BSW Communication Stacks (Release R4.1.3).</li>\n<li><strong>Architektur-Einordnung:</strong> SAE J1939 Kommunikationsstack (Services Layer & Hardware Abstraction Layer). Das Diagramm visualisiert die Trennung zwischen Request-Koordination/ACK-Generierung (<code>J1939Rm</code>), Diagnose-Verarbeitung (<code>J1939Dcm</code>), Routing (<code>PduR</code>) und CAN-Hardwareabstraktion (<code>CanIf</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte BSW-Module (Stereotyp <code>«module»</code>):</strong></li>\n<li><code>J1939Dcm</code>: J1939 Diagnostic Communication Manager. Verantwortlich für Diagnose-PGs, DTC-Status und Entscheidung über Datenbereitstellung vs. ACK/NACK.</li>\n<li><code>J1939Rm</code>: SAE J1939 Request Manager. Koordiniert eingehende Requests und zentralisiert das Erstellen und Versenden normkonformer J1939-Acknowledgements (PGN 59392 / <code>0xE800</code>).</li>\n<li><code>PduR</code>: PDU Router. Routet I-PDUs statisch anhand von PDU-IDs zwischen oberen Protokollmodulen und Schnittstellenmodulen.</li>\n<li><code>CanIf</code>: CAN Interface. Stellt den hardwareunabhängigen Zugriff auf CAN-Treiber/Mailboxen bereit.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & APIs:</strong></li>\n<li><code>J1939Rm_SendAck(uint8 node, const J1939Rm_AckType<em> ackInfo)</code> </em>(bzw. kanalspezifische Signatur)*: Synchroner Aufruf von <code>J1939Dcm</code> an <code>J1939Rm</code> zur Erzeugung eines Acknowledgements (Positive ACK, NACK, Access Denied, Cannot Respond / Busy).</li>\n<li><code>PduR_J1939DcmTransmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: PduR-Sende-API für Diagnose-PDUs.</li>\n<li><code>PduR_J1939RmTransmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: PduR-Sende-API für ACK-PDUs aus dem Request Manager.</li>\n<li><code>CanIf_Transmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: Übergabe der formatierten CAN-I-PDU an das CAN-Interface zur hardwarenahen Pufferung/Versendung.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Vorausgehende Interaktion (<code>ref J1939Rm Request Reception</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die eingehende Request-PDU (PGN 59904) wurde via <code>CanIf</code> $\\rightarrow$ <code>PduR</code> $\\rightarrow$ <code>J1939Rm</code> empfangen und an <code>J1939Dcm</code> weitergereicht.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entscheidungsknoten (<code>alt Request answered by</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Zweig 1: <code>[Requested PG]</code> (Erfolgreiche Datenbereitstellung):</strong></li>\n<li><code>J1939Dcm</code> serialisiert die angeforderte PG-Payload.</li>\n<li>Synchrone Auslösung von <code>PduR_J1939DcmTransmit()</code>.</li>\n<li><code>PduR</code> führt ID-Mapping durch und ruft synchron <code>CanIf_Transmit()</code> auf.</li>\n<li>Rückkehrkaskade (<code>Std_ReturnType</code>: <code>E_OK</code>/<code>E_NOT_OK</code>) zurück an <code>J1939Dcm</code>.</li>\n<li><strong>Zweig 2: <code>[Acknowledgement]</code> (Ablehnung, Zugriff verweigert oder Bestätigung):</strong></li>\n<li><code>J1939Dcm</code> kann oder darf die angeforderte PG nicht liefern (oder fordert ein explizites ACK).</li>\n<li><code>J1939Dcm</code> delegiert die Antworterzeugung via <code>J1939Rm_SendAck()</code> an den zentralen <code>J1939Rm</code>.</li>\n<li><code>J1939Rm</code> erzeugt die standardkonforme 8-Byte ACK-PDU (Byte 1: Control Byte, Bytes 2–4: Group Function / PGN, Bytes 5–8: Address).</li>\n<li><code>J1939Rm</code> triggert <code>PduR_J1939RmTransmit()</code>, welches wiederum <code>CanIf_Transmit()</code> aufruft.</li>\n<li>Synchrone Bestätigung des Sendeauftrags propagiert von <code>CanIf</code> über <code>PduR</code> und <code>J1939Rm</code> zurück zu <code>J1939Dcm</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PduR-Konfiguration:</strong></li>\n<li>Im PduR-Routingtable (<code>PduRRoutingTables</code>) müssen separate Pfade für <code>J1939Dcm</code>-Sende-PDUs und <code>J1939Rm</code>-ACK-PDUs konfiguriert sein (<code>PduRSrcPdu</code> $\\rightarrow$ <code>PduRDestPdu</code> Richtung <code>CanIf</code>).</li>\n<li><strong>Keine direkte ACK-Codierung im J1939Dcm:</strong></li>\n<li>Der Entwickler/Integrator darf ACK-Nachrichten für J1939-Diagnose-Requests nicht im <code>J1939Dcm</code> selbst erzeugen oder über eigene Dcm-PDUs senden. Die SAE-J1939-21/73-konforme ACK-Erzeugung ist im <code>J1939Rm</code> gekapselt (<code>J1939Rm_SendAck()</code>).</li>\n<li><strong>Synchroner API-Vertrag:</strong></li>\n<li><code>CanIf_Transmit()</code> und die PduR-Transmit-APIs quittieren lediglich die erfolgreiche Übernahme in den Hardware-Transmit-Buffer (<code>E_OK</code>) oder Pufferüberlauf/Offline-Zustand (<code>E_NOT_OK</code>). Die asynchrone Bestätigung des tatsächlichen Busversands erfolgt über nachgelagerte <code>&lt;User&gt;_TxConfirmation()</code>-Callbacks (im Diagramm abstrahiert).</li>\n<li><strong>Multi-Packet Einschränkung:</strong></li>\n<li>Das Diagramm zeigt die direkte Übertragung über <code>CanIf</code> (Single-Frame $\\le 8$ Bytes). Für Diagnose-PDUs $> 8$ Bytes (z. B. umfangreiche DM1/DM2-Listen) greift stattdessen der J1939 Transport Protocol Stack (<code>J1939Tp</code> via BAM oder RTS/CTS), welcher hier nicht durchlaufen wird.</li>\n</ul>"}, {"id": "FIG-baef09f7c18782d1", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm) mit Referenzierungsfragment (<code>ref</code>) und kombiniertem Fragment (<code>alt</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses zur Beantwortung einer zuvor empfangenen J1939-Anfrage (PGN 59904 / <code>Request PDU</code>) für eine Diagnose-PDU (z. B. DM-Nachrichten wie DM1–DM5) innerhalb des AUTOSAR Classic BSW Communication Stacks (Release R4.1.3).</li>\n<li><strong>Architektur-Einordnung:</strong> SAE J1939 Kommunikationsstack (Services Layer & Hardware Abstraction Layer). Das Diagramm visualisiert die Trennung zwischen Request-Koordination/ACK-Generierung (<code>J1939Rm</code>), Diagnose-Verarbeitung (<code>J1939Dcm</code>), Routing (<code>PduR</code>) und CAN-Hardwareabstraktion (<code>CanIf</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte BSW-Module (Stereotyp <code>«module»</code>):</strong></li>\n<li><code>J1939Dcm</code>: J1939 Diagnostic Communication Manager. Verantwortlich für Diagnose-PGs, DTC-Status und Entscheidung über Datenbereitstellung vs. ACK/NACK.</li>\n<li><code>J1939Rm</code>: SAE J1939 Request Manager. Koordiniert eingehende Requests und zentralisiert das Erstellen und Versenden normkonformer J1939-Acknowledgements (PGN 59392 / <code>0xE800</code>).</li>\n<li><code>PduR</code>: PDU Router. Routet I-PDUs statisch anhand von PDU-IDs zwischen oberen Protokollmodulen und Schnittstellenmodulen.</li>\n<li><code>CanIf</code>: CAN Interface. Stellt den hardwareunabhängigen Zugriff auf CAN-Treiber/Mailboxen bereit.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & APIs:</strong></li>\n<li><code>J1939Rm_SendAck(uint8 node, const J1939Rm_AckType<em> ackInfo)</code> </em>(bzw. kanalspezifische Signatur)*: Synchroner Aufruf von <code>J1939Dcm</code> an <code>J1939Rm</code> zur Erzeugung eines Acknowledgements (Positive ACK, NACK, Access Denied, Cannot Respond / Busy).</li>\n<li><code>PduR_J1939DcmTransmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: PduR-Sende-API für Diagnose-PDUs.</li>\n<li><code>PduR_J1939RmTransmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: PduR-Sende-API für ACK-PDUs aus dem Request Manager.</li>\n<li><code>CanIf_Transmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: Übergabe der formatierten CAN-I-PDU an das CAN-Interface zur hardwarenahen Pufferung/Versendung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Vorausgehende Interaktion (<code>ref J1939Rm Request Reception</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die eingehende Request-PDU (PGN 59904) wurde via <code>CanIf</code> $\\rightarrow$ <code>PduR</code> $\\rightarrow$ <code>J1939Rm</code> empfangen und an <code>J1939Dcm</code> weitergereicht.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entscheidungsknoten (<code>alt Request answered by</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Zweig 1: <code>[Requested PG]</code> (Erfolgreiche Datenbereitstellung):</strong></li>\n<li><code>J1939Dcm</code> serialisiert die angeforderte PG-Payload.</li>\n<li>Synchrone Auslösung von <code>PduR_J1939DcmTransmit()</code>.</li>\n<li><code>PduR</code> führt ID-Mapping durch und ruft synchron <code>CanIf_Transmit()</code> auf.</li>\n<li>Rückkehrkaskade (<code>Std_ReturnType</code>: <code>E_OK</code>/<code>E_NOT_OK</code>) zurück an <code>J1939Dcm</code>.</li>\n<li><strong>Zweig 2: <code>[Acknowledgement]</code> (Ablehnung, Zugriff verweigert oder Bestätigung):</strong></li>\n<li><code>J1939Dcm</code> kann oder darf die angeforderte PG nicht liefern (oder fordert ein explizites ACK).</li>\n<li><code>J1939Dcm</code> delegiert die Antworterzeugung via <code>J1939Rm_SendAck()</code> an den zentralen <code>J1939Rm</code>.</li>\n<li><code>J1939Rm</code> erzeugt die standardkonforme 8-Byte ACK-PDU (Byte 1: Control Byte, Bytes 2–4: Group Function / PGN, Bytes 5–8: Address).</li>\n<li><code>J1939Rm</code> triggert <code>PduR_J1939RmTransmit()</code>, welches wiederum <code>CanIf_Transmit()</code> aufruft.</li>\n<li>Synchrone Bestätigung des Sendeauftrags propagiert von <code>CanIf</code> über <code>PduR</code> und <code>J1939Rm</code> zurück zu <code>J1939Dcm</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PduR-Konfiguration:</strong></li>\n<li>Im PduR-Routingtable (<code>PduRRoutingTables</code>) müssen separate Pfade für <code>J1939Dcm</code>-Sende-PDUs und <code>J1939Rm</code>-ACK-PDUs konfiguriert sein (<code>PduRSrcPdu</code> $\\rightarrow$ <code>PduRDestPdu</code> Richtung <code>CanIf</code>).</li>\n<li><strong>Keine direkte ACK-Codierung im J1939Dcm:</strong></li>\n<li>Der Entwickler/Integrator darf ACK-Nachrichten für J1939-Diagnose-Requests nicht im <code>J1939Dcm</code> selbst erzeugen oder über eigene Dcm-PDUs senden. Die SAE-J1939-21/73-konforme ACK-Erzeugung ist im <code>J1939Rm</code> gekapselt (<code>J1939Rm_SendAck()</code>).</li>\n<li><strong>Synchroner API-Vertrag:</strong></li>\n<li><code>CanIf_Transmit()</code> und die PduR-Transmit-APIs quittieren lediglich die erfolgreiche Übernahme in den Hardware-Transmit-Buffer (<code>E_OK</code>) oder Pufferüberlauf/Offline-Zustand (<code>E_NOT_OK</code>). Die asynchrone Bestätigung des tatsächlichen Busversands erfolgt über nachgelagerte <code>&lt;User&gt;_TxConfirmation()</code>-Callbacks (im Diagramm abstrahiert).</li>\n<li><strong>Multi-Packet Einschränkung:</strong></li>\n<li>Das Diagramm zeigt die direkte Übertragung über <code>CanIf</code> (Single-Frame $\\le 8$ Bytes). Für Diagnose-PDUs $> 8$ Bytes (z. B. umfangreiche DM1/DM2-Listen) greift stattdessen der J1939 Transport Protocol Stack (<code>J1939Tp</code> via BAM oder RTS/CTS), welcher hier nicht durchlaufen wird.</li>\n</ul>"}, {"id": "FIG-0f5f9fcd32d46018", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm) mit Referenzierungsfragment (<code>ref</code>) und kombiniertem Fragment (<code>alt</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses zur Beantwortung einer zuvor empfangenen J1939-Anfrage (PGN 59904 / <code>Request PDU</code>) für eine Diagnose-PDU (z. B. DM-Nachrichten wie DM1–DM5) innerhalb des AUTOSAR Classic BSW Communication Stacks (Release R4.1.3).</li>\n<li><strong>Architektur-Einordnung:</strong> SAE J1939 Kommunikationsstack (Services Layer & Hardware Abstraction Layer). Das Diagramm visualisiert die Trennung zwischen Request-Koordination/ACK-Generierung (<code>J1939Rm</code>), Diagnose-Verarbeitung (<code>J1939Dcm</code>), Routing (<code>PduR</code>) und CAN-Hardwareabstraktion (<code>CanIf</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte BSW-Module (Stereotyp <code>«module»</code>):</strong></li>\n<li><code>J1939Dcm</code>: J1939 Diagnostic Communication Manager. Verantwortlich für Diagnose-PGs, DTC-Status und Entscheidung über Datenbereitstellung vs. ACK/NACK.</li>\n<li><code>J1939Rm</code>: SAE J1939 Request Manager. Koordiniert eingehende Requests und zentralisiert das Erstellen und Versenden normkonformer J1939-Acknowledgements (PGN 59392 / <code>0xE800</code>).</li>\n<li><code>PduR</code>: PDU Router. Routet I-PDUs statisch anhand von PDU-IDs zwischen oberen Protokollmodulen und Schnittstellenmodulen.</li>\n<li><code>CanIf</code>: CAN Interface. Stellt den hardwareunabhängigen Zugriff auf CAN-Treiber/Mailboxen bereit.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & APIs:</strong></li>\n<li><code>J1939Rm_SendAck(uint8 node, const J1939Rm_AckType<em> ackInfo)</code> </em>(bzw. kanalspezifische Signatur)*: Synchroner Aufruf von <code>J1939Dcm</code> an <code>J1939Rm</code> zur Erzeugung eines Acknowledgements (Positive ACK, NACK, Access Denied, Cannot Respond / Busy).</li>\n<li><code>PduR_J1939DcmTransmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: PduR-Sende-API für Diagnose-PDUs.</li>\n<li><code>PduR_J1939RmTransmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: PduR-Sende-API für ACK-PDUs aus dem Request Manager.</li>\n<li><code>CanIf_Transmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: Übergabe der formatierten CAN-I-PDU an das CAN-Interface zur hardwarenahen Pufferung/Versendung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Vorausgehende Interaktion (<code>ref J1939Rm Request Reception</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die eingehende Request-PDU (PGN 59904) wurde via <code>CanIf</code> $\\rightarrow$ <code>PduR</code> $\\rightarrow$ <code>J1939Rm</code> empfangen und an <code>J1939Dcm</code> weitergereicht.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entscheidungsknoten (<code>alt Request answered by</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Zweig 1: <code>[Requested PG]</code> (Erfolgreiche Datenbereitstellung):</strong></li>\n<li><code>J1939Dcm</code> serialisiert die angeforderte PG-Payload.</li>\n<li>Synchrone Auslösung von <code>PduR_J1939DcmTransmit()</code>.</li>\n<li><code>PduR</code> führt ID-Mapping durch und ruft synchron <code>CanIf_Transmit()</code> auf.</li>\n<li>Rückkehrkaskade (<code>Std_ReturnType</code>: <code>E_OK</code>/<code>E_NOT_OK</code>) zurück an <code>J1939Dcm</code>.</li>\n<li><strong>Zweig 2: <code>[Acknowledgement]</code> (Ablehnung, Zugriff verweigert oder Bestätigung):</strong></li>\n<li><code>J1939Dcm</code> kann oder darf die angeforderte PG nicht liefern (oder fordert ein explizites ACK).</li>\n<li><code>J1939Dcm</code> delegiert die Antworterzeugung via <code>J1939Rm_SendAck()</code> an den zentralen <code>J1939Rm</code>.</li>\n<li><code>J1939Rm</code> erzeugt die standardkonforme 8-Byte ACK-PDU (Byte 1: Control Byte, Bytes 2–4: Group Function / PGN, Bytes 5–8: Address).</li>\n<li><code>J1939Rm</code> triggert <code>PduR_J1939RmTransmit()</code>, welches wiederum <code>CanIf_Transmit()</code> aufruft.</li>\n<li>Synchrone Bestätigung des Sendeauftrags propagiert von <code>CanIf</code> über <code>PduR</code> und <code>J1939Rm</code> zurück zu <code>J1939Dcm</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PduR-Konfiguration:</strong></li>\n<li>Im PduR-Routingtable (<code>PduRRoutingTables</code>) müssen separate Pfade für <code>J1939Dcm</code>-Sende-PDUs und <code>J1939Rm</code>-ACK-PDUs konfiguriert sein (<code>PduRSrcPdu</code> $\\rightarrow$ <code>PduRDestPdu</code> Richtung <code>CanIf</code>).</li>\n<li><strong>Keine direkte ACK-Codierung im J1939Dcm:</strong></li>\n<li>Der Entwickler/Integrator darf ACK-Nachrichten für J1939-Diagnose-Requests nicht im <code>J1939Dcm</code> selbst erzeugen oder über eigene Dcm-PDUs senden. Die SAE-J1939-21/73-konforme ACK-Erzeugung ist im <code>J1939Rm</code> gekapselt (<code>J1939Rm_SendAck()</code>).</li>\n<li><strong>Synchroner API-Vertrag:</strong></li>\n<li><code>CanIf_Transmit()</code> und die PduR-Transmit-APIs quittieren lediglich die erfolgreiche Übernahme in den Hardware-Transmit-Buffer (<code>E_OK</code>) oder Pufferüberlauf/Offline-Zustand (<code>E_NOT_OK</code>). Die asynchrone Bestätigung des tatsächlichen Busversands erfolgt über nachgelagerte <code>&lt;User&gt;_TxConfirmation()</code>-Callbacks (im Diagramm abstrahiert).</li>\n<li><strong>Multi-Packet Einschränkung:</strong></li>\n<li>Das Diagramm zeigt die direkte Übertragung über <code>CanIf</code> (Single-Frame $\\le 8$ Bytes). Für Diagnose-PDUs $> 8$ Bytes (z. B. umfangreiche DM1/DM2-Listen) greift stattdessen der J1939 Transport Protocol Stack (<code>J1939Tp</code> via BAM oder RTS/CTS), welcher hier nicht durchlaufen wird.</li>\n</ul>"}, {"id": "FIG-c7f32fefb23ea3c8", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm) mit Referenzierungsfragment (<code>ref</code>) und kombiniertem Fragment (<code>alt</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses zur Beantwortung einer zuvor empfangenen J1939-Anfrage (PGN 59904 / <code>Request PDU</code>) für eine Diagnose-PDU (z. B. DM-Nachrichten wie DM1–DM5) innerhalb des AUTOSAR Classic BSW Communication Stacks (Release R4.1.3).</li>\n<li><strong>Architektur-Einordnung:</strong> SAE J1939 Kommunikationsstack (Services Layer & Hardware Abstraction Layer). Das Diagramm visualisiert die Trennung zwischen Request-Koordination/ACK-Generierung (<code>J1939Rm</code>), Diagnose-Verarbeitung (<code>J1939Dcm</code>), Routing (<code>PduR</code>) und CAN-Hardwareabstraktion (<code>CanIf</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte BSW-Module (Stereotyp <code>«module»</code>):</strong></li>\n<li><code>J1939Dcm</code>: J1939 Diagnostic Communication Manager. Verantwortlich für Diagnose-PGs, DTC-Status und Entscheidung über Datenbereitstellung vs. ACK/NACK.</li>\n<li><code>J1939Rm</code>: SAE J1939 Request Manager. Koordiniert eingehende Requests und zentralisiert das Erstellen und Versenden normkonformer J1939-Acknowledgements (PGN 59392 / <code>0xE800</code>).</li>\n<li><code>PduR</code>: PDU Router. Routet I-PDUs statisch anhand von PDU-IDs zwischen oberen Protokollmodulen und Schnittstellenmodulen.</li>\n<li><code>CanIf</code>: CAN Interface. Stellt den hardwareunabhängigen Zugriff auf CAN-Treiber/Mailboxen bereit.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & APIs:</strong></li>\n<li><code>J1939Rm_SendAck(uint8 node, const J1939Rm_AckType<em> ackInfo)</code> </em>(bzw. kanalspezifische Signatur)*: Synchroner Aufruf von <code>J1939Dcm</code> an <code>J1939Rm</code> zur Erzeugung eines Acknowledgements (Positive ACK, NACK, Access Denied, Cannot Respond / Busy).</li>\n<li><code>PduR_J1939DcmTransmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: PduR-Sende-API für Diagnose-PDUs.</li>\n<li><code>PduR_J1939RmTransmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: PduR-Sende-API für ACK-PDUs aus dem Request Manager.</li>\n<li><code>CanIf_Transmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: Übergabe der formatierten CAN-I-PDU an das CAN-Interface zur hardwarenahen Pufferung/Versendung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Vorausgehende Interaktion (<code>ref J1939Rm Request Reception</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die eingehende Request-PDU (PGN 59904) wurde via <code>CanIf</code> $\\rightarrow$ <code>PduR</code> $\\rightarrow$ <code>J1939Rm</code> empfangen und an <code>J1939Dcm</code> weitergereicht.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entscheidungsknoten (<code>alt Request answered by</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Zweig 1: <code>[Requested PG]</code> (Erfolgreiche Datenbereitstellung):</strong></li>\n<li><code>J1939Dcm</code> serialisiert die angeforderte PG-Payload.</li>\n<li>Synchrone Auslösung von <code>PduR_J1939DcmTransmit()</code>.</li>\n<li><code>PduR</code> führt ID-Mapping durch und ruft synchron <code>CanIf_Transmit()</code> auf.</li>\n<li>Rückkehrkaskade (<code>Std_ReturnType</code>: <code>E_OK</code>/<code>E_NOT_OK</code>) zurück an <code>J1939Dcm</code>.</li>\n<li><strong>Zweig 2: <code>[Acknowledgement]</code> (Ablehnung, Zugriff verweigert oder Bestätigung):</strong></li>\n<li><code>J1939Dcm</code> kann oder darf die angeforderte PG nicht liefern (oder fordert ein explizites ACK).</li>\n<li><code>J1939Dcm</code> delegiert die Antworterzeugung via <code>J1939Rm_SendAck()</code> an den zentralen <code>J1939Rm</code>.</li>\n<li><code>J1939Rm</code> erzeugt die standardkonforme 8-Byte ACK-PDU (Byte 1: Control Byte, Bytes 2–4: Group Function / PGN, Bytes 5–8: Address).</li>\n<li><code>J1939Rm</code> triggert <code>PduR_J1939RmTransmit()</code>, welches wiederum <code>CanIf_Transmit()</code> aufruft.</li>\n<li>Synchrone Bestätigung des Sendeauftrags propagiert von <code>CanIf</code> über <code>PduR</code> und <code>J1939Rm</code> zurück zu <code>J1939Dcm</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PduR-Konfiguration:</strong></li>\n<li>Im PduR-Routingtable (<code>PduRRoutingTables</code>) müssen separate Pfade für <code>J1939Dcm</code>-Sende-PDUs und <code>J1939Rm</code>-ACK-PDUs konfiguriert sein (<code>PduRSrcPdu</code> $\\rightarrow$ <code>PduRDestPdu</code> Richtung <code>CanIf</code>).</li>\n<li><strong>Keine direkte ACK-Codierung im J1939Dcm:</strong></li>\n<li>Der Entwickler/Integrator darf ACK-Nachrichten für J1939-Diagnose-Requests nicht im <code>J1939Dcm</code> selbst erzeugen oder über eigene Dcm-PDUs senden. Die SAE-J1939-21/73-konforme ACK-Erzeugung ist im <code>J1939Rm</code> gekapselt (<code>J1939Rm_SendAck()</code>).</li>\n<li><strong>Synchroner API-Vertrag:</strong></li>\n<li><code>CanIf_Transmit()</code> und die PduR-Transmit-APIs quittieren lediglich die erfolgreiche Übernahme in den Hardware-Transmit-Buffer (<code>E_OK</code>) oder Pufferüberlauf/Offline-Zustand (<code>E_NOT_OK</code>). Die asynchrone Bestätigung des tatsächlichen Busversands erfolgt über nachgelagerte <code>&lt;User&gt;_TxConfirmation()</code>-Callbacks (im Diagramm abstrahiert).</li>\n<li><strong>Multi-Packet Einschränkung:</strong></li>\n<li>Das Diagramm zeigt die direkte Übertragung über <code>CanIf</code> (Single-Frame $\\le 8$ Bytes). Für Diagnose-PDUs $> 8$ Bytes (z. B. umfangreiche DM1/DM2-Listen) greift stattdessen der J1939 Transport Protocol Stack (<code>J1939Tp</code> via BAM oder RTS/CTS), welcher hier nicht durchlaufen wird.</li>\n</ul>"}, {"id": "FIG-e7c6c2afb28a5f0b", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm) mit Referenzierungsfragment (<code>ref</code>) und kombiniertem Fragment (<code>alt</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses zur Beantwortung einer zuvor empfangenen J1939-Anfrage (PGN 59904 / <code>Request PDU</code>) für eine Diagnose-PDU (z. B. DM-Nachrichten wie DM1–DM5) innerhalb des AUTOSAR Classic BSW Communication Stacks (Release R4.1.3).</li>\n<li><strong>Architektur-Einordnung:</strong> SAE J1939 Kommunikationsstack (Services Layer & Hardware Abstraction Layer). Das Diagramm visualisiert die Trennung zwischen Request-Koordination/ACK-Generierung (<code>J1939Rm</code>), Diagnose-Verarbeitung (<code>J1939Dcm</code>), Routing (<code>PduR</code>) und CAN-Hardwareabstraktion (<code>CanIf</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte BSW-Module (Stereotyp <code>«module»</code>):</strong></li>\n<li><code>J1939Dcm</code>: J1939 Diagnostic Communication Manager. Verantwortlich für Diagnose-PGs, DTC-Status und Entscheidung über Datenbereitstellung vs. ACK/NACK.</li>\n<li><code>J1939Rm</code>: SAE J1939 Request Manager. Koordiniert eingehende Requests und zentralisiert das Erstellen und Versenden normkonformer J1939-Acknowledgements (PGN 59392 / <code>0xE800</code>).</li>\n<li><code>PduR</code>: PDU Router. Routet I-PDUs statisch anhand von PDU-IDs zwischen oberen Protokollmodulen und Schnittstellenmodulen.</li>\n<li><code>CanIf</code>: CAN Interface. Stellt den hardwareunabhängigen Zugriff auf CAN-Treiber/Mailboxen bereit.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & APIs:</strong></li>\n<li><code>J1939Rm_SendAck(uint8 node, const J1939Rm_AckType<em> ackInfo)</code> </em>(bzw. kanalspezifische Signatur)*: Synchroner Aufruf von <code>J1939Dcm</code> an <code>J1939Rm</code> zur Erzeugung eines Acknowledgements (Positive ACK, NACK, Access Denied, Cannot Respond / Busy).</li>\n<li><code>PduR_J1939DcmTransmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: PduR-Sende-API für Diagnose-PDUs.</li>\n<li><code>PduR_J1939RmTransmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: PduR-Sende-API für ACK-PDUs aus dem Request Manager.</li>\n<li><code>CanIf_Transmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: Übergabe der formatierten CAN-I-PDU an das CAN-Interface zur hardwarenahen Pufferung/Versendung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Vorausgehende Interaktion (<code>ref J1939Rm Request Reception</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die eingehende Request-PDU (PGN 59904) wurde via <code>CanIf</code> $\\rightarrow$ <code>PduR</code> $\\rightarrow$ <code>J1939Rm</code> empfangen und an <code>J1939Dcm</code> weitergereicht.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entscheidungsknoten (<code>alt Request answered by</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Zweig 1: <code>[Requested PG]</code> (Erfolgreiche Datenbereitstellung):</strong></li>\n<li><code>J1939Dcm</code> serialisiert die angeforderte PG-Payload.</li>\n<li>Synchrone Auslösung von <code>PduR_J1939DcmTransmit()</code>.</li>\n<li><code>PduR</code> führt ID-Mapping durch und ruft synchron <code>CanIf_Transmit()</code> auf.</li>\n<li>Rückkehrkaskade (<code>Std_ReturnType</code>: <code>E_OK</code>/<code>E_NOT_OK</code>) zurück an <code>J1939Dcm</code>.</li>\n<li><strong>Zweig 2: <code>[Acknowledgement]</code> (Ablehnung, Zugriff verweigert oder Bestätigung):</strong></li>\n<li><code>J1939Dcm</code> kann oder darf die angeforderte PG nicht liefern (oder fordert ein explizites ACK).</li>\n<li><code>J1939Dcm</code> delegiert die Antworterzeugung via <code>J1939Rm_SendAck()</code> an den zentralen <code>J1939Rm</code>.</li>\n<li><code>J1939Rm</code> erzeugt die standardkonforme 8-Byte ACK-PDU (Byte 1: Control Byte, Bytes 2–4: Group Function / PGN, Bytes 5–8: Address).</li>\n<li><code>J1939Rm</code> triggert <code>PduR_J1939RmTransmit()</code>, welches wiederum <code>CanIf_Transmit()</code> aufruft.</li>\n<li>Synchrone Bestätigung des Sendeauftrags propagiert von <code>CanIf</code> über <code>PduR</code> und <code>J1939Rm</code> zurück zu <code>J1939Dcm</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PduR-Konfiguration:</strong></li>\n<li>Im PduR-Routingtable (<code>PduRRoutingTables</code>) müssen separate Pfade für <code>J1939Dcm</code>-Sende-PDUs und <code>J1939Rm</code>-ACK-PDUs konfiguriert sein (<code>PduRSrcPdu</code> $\\rightarrow$ <code>PduRDestPdu</code> Richtung <code>CanIf</code>).</li>\n<li><strong>Keine direkte ACK-Codierung im J1939Dcm:</strong></li>\n<li>Der Entwickler/Integrator darf ACK-Nachrichten für J1939-Diagnose-Requests nicht im <code>J1939Dcm</code> selbst erzeugen oder über eigene Dcm-PDUs senden. Die SAE-J1939-21/73-konforme ACK-Erzeugung ist im <code>J1939Rm</code> gekapselt (<code>J1939Rm_SendAck()</code>).</li>\n<li><strong>Synchroner API-Vertrag:</strong></li>\n<li><code>CanIf_Transmit()</code> und die PduR-Transmit-APIs quittieren lediglich die erfolgreiche Übernahme in den Hardware-Transmit-Buffer (<code>E_OK</code>) oder Pufferüberlauf/Offline-Zustand (<code>E_NOT_OK</code>). Die asynchrone Bestätigung des tatsächlichen Busversands erfolgt über nachgelagerte <code>&lt;User&gt;_TxConfirmation()</code>-Callbacks (im Diagramm abstrahiert).</li>\n<li><strong>Multi-Packet Einschränkung:</strong></li>\n<li>Das Diagramm zeigt die direkte Übertragung über <code>CanIf</code> (Single-Frame $\\le 8$ Bytes). Für Diagnose-PDUs $> 8$ Bytes (z. B. umfangreiche DM1/DM2-Listen) greift stattdessen der J1939 Transport Protocol Stack (<code>J1939Tp</code> via BAM oder RTS/CTS), welcher hier nicht durchlaufen wird.</li>\n</ul>"}, {"id": "FIG-72279d9321991102", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm) mit Referenzierungsfragment (<code>ref</code>) und kombiniertem Fragment (<code>alt</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses zur Beantwortung einer zuvor empfangenen J1939-Anfrage (PGN 59904 / <code>Request PDU</code>) für eine Diagnose-PDU (z. B. DM-Nachrichten wie DM1–DM5) innerhalb des AUTOSAR Classic BSW Communication Stacks (Release R4.1.3).</li>\n<li><strong>Architektur-Einordnung:</strong> SAE J1939 Kommunikationsstack (Services Layer & Hardware Abstraction Layer). Das Diagramm visualisiert die Trennung zwischen Request-Koordination/ACK-Generierung (<code>J1939Rm</code>), Diagnose-Verarbeitung (<code>J1939Dcm</code>), Routing (<code>PduR</code>) und CAN-Hardwareabstraktion (<code>CanIf</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte BSW-Module (Stereotyp <code>«module»</code>):</strong></li>\n<li><code>J1939Dcm</code>: J1939 Diagnostic Communication Manager. Verantwortlich für Diagnose-PGs, DTC-Status und Entscheidung über Datenbereitstellung vs. ACK/NACK.</li>\n<li><code>J1939Rm</code>: SAE J1939 Request Manager. Koordiniert eingehende Requests und zentralisiert das Erstellen und Versenden normkonformer J1939-Acknowledgements (PGN 59392 / <code>0xE800</code>).</li>\n<li><code>PduR</code>: PDU Router. Routet I-PDUs statisch anhand von PDU-IDs zwischen oberen Protokollmodulen und Schnittstellenmodulen.</li>\n<li><code>CanIf</code>: CAN Interface. Stellt den hardwareunabhängigen Zugriff auf CAN-Treiber/Mailboxen bereit.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & APIs:</strong></li>\n<li><code>J1939Rm_SendAck(uint8 node, const J1939Rm_AckType<em> ackInfo)</code> </em>(bzw. kanalspezifische Signatur)*: Synchroner Aufruf von <code>J1939Dcm</code> an <code>J1939Rm</code> zur Erzeugung eines Acknowledgements (Positive ACK, NACK, Access Denied, Cannot Respond / Busy).</li>\n<li><code>PduR_J1939DcmTransmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: PduR-Sende-API für Diagnose-PDUs.</li>\n<li><code>PduR_J1939RmTransmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: PduR-Sende-API für ACK-PDUs aus dem Request Manager.</li>\n<li><code>CanIf_Transmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: Übergabe der formatierten CAN-I-PDU an das CAN-Interface zur hardwarenahen Pufferung/Versendung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Vorausgehende Interaktion (<code>ref J1939Rm Request Reception</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die eingehende Request-PDU (PGN 59904) wurde via <code>CanIf</code> $\\rightarrow$ <code>PduR</code> $\\rightarrow$ <code>J1939Rm</code> empfangen und an <code>J1939Dcm</code> weitergereicht.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entscheidungsknoten (<code>alt Request answered by</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Zweig 1: <code>[Requested PG]</code> (Erfolgreiche Datenbereitstellung):</strong></li>\n<li><code>J1939Dcm</code> serialisiert die angeforderte PG-Payload.</li>\n<li>Synchrone Auslösung von <code>PduR_J1939DcmTransmit()</code>.</li>\n<li><code>PduR</code> führt ID-Mapping durch und ruft synchron <code>CanIf_Transmit()</code> auf.</li>\n<li>Rückkehrkaskade (<code>Std_ReturnType</code>: <code>E_OK</code>/<code>E_NOT_OK</code>) zurück an <code>J1939Dcm</code>.</li>\n<li><strong>Zweig 2: <code>[Acknowledgement]</code> (Ablehnung, Zugriff verweigert oder Bestätigung):</strong></li>\n<li><code>J1939Dcm</code> kann oder darf die angeforderte PG nicht liefern (oder fordert ein explizites ACK).</li>\n<li><code>J1939Dcm</code> delegiert die Antworterzeugung via <code>J1939Rm_SendAck()</code> an den zentralen <code>J1939Rm</code>.</li>\n<li><code>J1939Rm</code> erzeugt die standardkonforme 8-Byte ACK-PDU (Byte 1: Control Byte, Bytes 2–4: Group Function / PGN, Bytes 5–8: Address).</li>\n<li><code>J1939Rm</code> triggert <code>PduR_J1939RmTransmit()</code>, welches wiederum <code>CanIf_Transmit()</code> aufruft.</li>\n<li>Synchrone Bestätigung des Sendeauftrags propagiert von <code>CanIf</code> über <code>PduR</code> und <code>J1939Rm</code> zurück zu <code>J1939Dcm</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PduR-Konfiguration:</strong></li>\n<li>Im PduR-Routingtable (<code>PduRRoutingTables</code>) müssen separate Pfade für <code>J1939Dcm</code>-Sende-PDUs und <code>J1939Rm</code>-ACK-PDUs konfiguriert sein (<code>PduRSrcPdu</code> $\\rightarrow$ <code>PduRDestPdu</code> Richtung <code>CanIf</code>).</li>\n<li><strong>Keine direkte ACK-Codierung im J1939Dcm:</strong></li>\n<li>Der Entwickler/Integrator darf ACK-Nachrichten für J1939-Diagnose-Requests nicht im <code>J1939Dcm</code> selbst erzeugen oder über eigene Dcm-PDUs senden. Die SAE-J1939-21/73-konforme ACK-Erzeugung ist im <code>J1939Rm</code> gekapselt (<code>J1939Rm_SendAck()</code>).</li>\n<li><strong>Synchroner API-Vertrag:</strong></li>\n<li><code>CanIf_Transmit()</code> und die PduR-Transmit-APIs quittieren lediglich die erfolgreiche Übernahme in den Hardware-Transmit-Buffer (<code>E_OK</code>) oder Pufferüberlauf/Offline-Zustand (<code>E_NOT_OK</code>). Die asynchrone Bestätigung des tatsächlichen Busversands erfolgt über nachgelagerte <code>&lt;User&gt;_TxConfirmation()</code>-Callbacks (im Diagramm abstrahiert).</li>\n<li><strong>Multi-Packet Einschränkung:</strong></li>\n<li>Das Diagramm zeigt die direkte Übertragung über <code>CanIf</code> (Single-Frame $\\le 8$ Bytes). Für Diagnose-PDUs $> 8$ Bytes (z. B. umfangreiche DM1/DM2-Listen) greift stattdessen der J1939 Transport Protocol Stack (<code>J1939Tp</code> via BAM oder RTS/CTS), welcher hier nicht durchlaufen wird.</li>\n</ul>"}, {"id": "FIG-58b6ad0cbb0a1d6a", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm) mit Referenzierungsfragment (<code>ref</code>) und kombiniertem Fragment (<code>alt</code>).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Kontrollflusses zur Beantwortung einer zuvor empfangenen J1939-Anfrage (PGN 59904 / <code>Request PDU</code>) für eine Diagnose-PDU (z. B. DM-Nachrichten wie DM1–DM5) innerhalb des AUTOSAR Classic BSW Communication Stacks (Release R4.1.3).</li>\n<li><strong>Architektur-Einordnung:</strong> SAE J1939 Kommunikationsstack (Services Layer & Hardware Abstraction Layer). Das Diagramm visualisiert die Trennung zwischen Request-Koordination/ACK-Generierung (<code>J1939Rm</code>), Diagnose-Verarbeitung (<code>J1939Dcm</code>), Routing (<code>PduR</code>) und CAN-Hardwareabstraktion (<code>CanIf</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Beteiligte BSW-Module (Stereotyp <code>«module»</code>):</strong></li>\n<li><code>J1939Dcm</code>: J1939 Diagnostic Communication Manager. Verantwortlich für Diagnose-PGs, DTC-Status und Entscheidung über Datenbereitstellung vs. ACK/NACK.</li>\n<li><code>J1939Rm</code>: SAE J1939 Request Manager. Koordiniert eingehende Requests und zentralisiert das Erstellen und Versenden normkonformer J1939-Acknowledgements (PGN 59392 / <code>0xE800</code>).</li>\n<li><code>PduR</code>: PDU Router. Routet I-PDUs statisch anhand von PDU-IDs zwischen oberen Protokollmodulen und Schnittstellenmodulen.</li>\n<li><code>CanIf</code>: CAN Interface. Stellt den hardwareunabhängigen Zugriff auf CAN-Treiber/Mailboxen bereit.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & APIs:</strong></li>\n<li><code>J1939Rm_SendAck(uint8 node, const J1939Rm_AckType<em> ackInfo)</code> </em>(bzw. kanalspezifische Signatur)*: Synchroner Aufruf von <code>J1939Dcm</code> an <code>J1939Rm</code> zur Erzeugung eines Acknowledgements (Positive ACK, NACK, Access Denied, Cannot Respond / Busy).</li>\n<li><code>PduR_J1939DcmTransmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: PduR-Sende-API für Diagnose-PDUs.</li>\n<li><code>PduR_J1939RmTransmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: PduR-Sende-API für ACK-PDUs aus dem Request Manager.</li>\n<li><code>CanIf_Transmit(PduIdType TxPduId, const PduInfoType* PduInfoPtr)</code>: Übergabe der formatierten CAN-I-PDU an das CAN-Interface zur hardwarenahen Pufferung/Versendung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Vorausgehende Interaktion (<code>ref J1939Rm Request Reception</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die eingehende Request-PDU (PGN 59904) wurde via <code>CanIf</code> $\\rightarrow$ <code>PduR</code> $\\rightarrow$ <code>J1939Rm</code> empfangen und an <code>J1939Dcm</code> weitergereicht.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entscheidungsknoten (<code>alt Request answered by</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Zweig 1: <code>[Requested PG]</code> (Erfolgreiche Datenbereitstellung):</strong></li>\n<li><code>J1939Dcm</code> serialisiert die angeforderte PG-Payload.</li>\n<li>Synchrone Auslösung von <code>PduR_J1939DcmTransmit()</code>.</li>\n<li><code>PduR</code> führt ID-Mapping durch und ruft synchron <code>CanIf_Transmit()</code> auf.</li>\n<li>Rückkehrkaskade (<code>Std_ReturnType</code>: <code>E_OK</code>/<code>E_NOT_OK</code>) zurück an <code>J1939Dcm</code>.</li>\n<li><strong>Zweig 2: <code>[Acknowledgement]</code> (Ablehnung, Zugriff verweigert oder Bestätigung):</strong></li>\n<li><code>J1939Dcm</code> kann oder darf die angeforderte PG nicht liefern (oder fordert ein explizites ACK).</li>\n<li><code>J1939Dcm</code> delegiert die Antworterzeugung via <code>J1939Rm_SendAck()</code> an den zentralen <code>J1939Rm</code>.</li>\n<li><code>J1939Rm</code> erzeugt die standardkonforme 8-Byte ACK-PDU (Byte 1: Control Byte, Bytes 2–4: Group Function / PGN, Bytes 5–8: Address).</li>\n<li><code>J1939Rm</code> triggert <code>PduR_J1939RmTransmit()</code>, welches wiederum <code>CanIf_Transmit()</code> aufruft.</li>\n<li>Synchrone Bestätigung des Sendeauftrags propagiert von <code>CanIf</code> über <code>PduR</code> und <code>J1939Rm</code> zurück zu <code>J1939Dcm</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PduR-Konfiguration:</strong></li>\n<li>Im PduR-Routingtable (<code>PduRRoutingTables</code>) müssen separate Pfade für <code>J1939Dcm</code>-Sende-PDUs und <code>J1939Rm</code>-ACK-PDUs konfiguriert sein (<code>PduRSrcPdu</code> $\\rightarrow$ <code>PduRDestPdu</code> Richtung <code>CanIf</code>).</li>\n<li><strong>Keine direkte ACK-Codierung im J1939Dcm:</strong></li>\n<li>Der Entwickler/Integrator darf ACK-Nachrichten für J1939-Diagnose-Requests nicht im <code>J1939Dcm</code> selbst erzeugen oder über eigene Dcm-PDUs senden. Die SAE-J1939-21/73-konforme ACK-Erzeugung ist im <code>J1939Rm</code> gekapselt (<code>J1939Rm_SendAck()</code>).</li>\n<li><strong>Synchroner API-Vertrag:</strong></li>\n<li><code>CanIf_Transmit()</code> und die PduR-Transmit-APIs quittieren lediglich die erfolgreiche Übernahme in den Hardware-Transmit-Buffer (<code>E_OK</code>) oder Pufferüberlauf/Offline-Zustand (<code>E_NOT_OK</code>). Die asynchrone Bestätigung des tatsächlichen Busversands erfolgt über nachgelagerte <code>&lt;User&gt;_TxConfirmation()</code>-Callbacks (im Diagramm abstrahiert).</li>\n<li><strong>Multi-Packet Einschränkung:</strong></li>\n<li>Das Diagramm zeigt die direkte Übertragung über <code>CanIf</code> (Single-Frame $\\le 8$ Bytes). Für Diagnose-PDUs $> 8$ Bytes (z. B. umfangreiche DM1/DM2-Listen) greift stattdessen der J1939 Transport Protocol Stack (<code>J1939Tp</code> via BAM oder RTS/CTS), welcher hier nicht durchlaufen wird.</li>\n</ul>"}], "trans": [{"from": "FIG-23080b25cdd4f298", "to": "FIG-baef09f7c18782d1", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-baef09f7c18782d1", "to": "FIG-0f5f9fcd32d46018", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0f5f9fcd32d46018", "to": "FIG-c7f32fefb23ea3c8", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c7f32fefb23ea3c8", "to": "FIG-e7c6c2afb28a5f0b", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e7c6c2afb28a5f0b", "to": "FIG-72279d9321991102", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-72279d9321991102", "to": "FIG-58b6ad0cbb0a1d6a", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
